// Title: [SW][QA][Login] Login in Saucedemo App
// Augmented by: SW-15 (2026-09-07)
// Manual edits are welcome — this file is not regenerated automatically.
// Re-running /from-issue against a contributing issue will refuse to overwrite.

import { test, expect } from '@fixtures/test';
import { env } from '@utils/env';

test.describe('login — no auth', { tag: '@no-auth' }, () => {
  test.describe('Positive', () => {
    // Scenario 1: every valid user logs in and lands on the Products page.
    const validUsers = [
      'standard_user',
      'problem_user',
      'performance_glitch_user',
      'error_user',
      'visual_user',
    ];

    for (const user of validUsers) {
      // Keep the smoke set tight: only the canonical standard_user gates builds.
      test(
        `${user} logs in successfully and lands on inventory`,
        user === 'standard_user' ? { tag: '@smoke' } : {},
        async ({ loginPage, page }) => {
          await loginPage.goto();
          await loginPage.loginAs(user, env.password);
          await expect(page).toHaveURL(/\/inventory\.html$/);
        },
      );
    }
  });

  test.describe('Negative', () => {
    // Scenarios 2 + 3: missing required fields surface the right validation error.
    const requiredFieldCases = [
      {
        username: '',
        password: '',
        error: 'Epic sadface: Username is required',
        desc: 'no credentials',
      },
      {
        username: 'standard_user',
        password: '',
        error: 'Epic sadface: Password is required',
        desc: 'missing password',
      },
      {
        username: '',
        password: env.password,
        error: 'Epic sadface: Username is required',
        desc: 'missing username',
      },
    ];

    for (const { username, password, error, desc } of requiredFieldCases) {
      test(`${desc} shows the required-field error`, async ({ loginPage }) => {
        await loginPage.goto();
        await loginPage.loginAs(username, password);
        await expect(loginPage.errorBanner).toBeVisible();
        await expect(loginPage.errorBanner).toHaveText(error);
      });
    }

    // Scenario 4: invalid credentials are rejected with the standard error.
    test('invalid credentials are rejected', { tag: '@smoke' }, async ({ loginPage }) => {
      await loginPage.goto();
      await loginPage.loginAs('invalid_user', 'wrong_password');
      await expect(loginPage.errorBanner).toBeVisible();
      await expect(loginPage.errorBanner).toHaveText(
        'Epic sadface: Username and password do not match any user in this service',
      );
    });

    // SW-15 AC 1 + AC 2 — one action (submit correct credentials for a locked account)
    // observed at two points, so one test: the rejection and the message that explains it.
    test(
      'locked_out_user is rejected with the lockout error',
      { tag: '@smoke' },
      async ({ loginPage, page }) => {
        await loginPage.goto();
        await loginPage.loginAs('locked_out_user', env.password);

        await expect(loginPage.errorBanner).toBeVisible();
        await expect(loginPage.errorBanner).toHaveText(
          'Epic sadface: Sorry, this user has been locked out.',
        );

        // AC 1 — authentication never happens. Asserted in positive form: the login form
        // is still on screen and the URL never became the inventory page. A bare
        // `not.toHaveURL(/inventory/)` would pass trivially before any navigation.
        await expect(loginPage.loginButton).toBeVisible();
        await expect(page).toHaveURL(/saucedemo\.com\/?$/);
      },
    );
  });

  test.describe('Edge', () => {
    // SW-15 AC 3 — which rejection wins when both could apply. The credential check runs
    // first, so a wrong password never reveals that the account is locked. Asserting the
    // absence of the lockout string is the point: it is what stops a future change from
    // leaking account state to someone who does not hold the password.
    //
    // AC 3 originally claimed the opposite. The run that found otherwise stopped and
    // reported rather than rewriting this expectation — the criterion was corrected on
    // the ticket first, and this test follows the corrected criterion.
    test('locked_out_user with a wrong password sees the credentials error, not the lockout error', async ({
      loginPage,
    }) => {
      await loginPage.goto();
      await loginPage.loginAs('locked_out_user', 'wrong_password');

      await expect(loginPage.errorBanner).toBeVisible();
      await expect(loginPage.errorBanner).toHaveText(
        'Epic sadface: Username and password do not match any user in this service',
      );
    });
  });
});
